         format!("FAILED: {} file(s) did not land", c.files_failed)
     } else {
         "ok".to_string()
     };
     eprintln!(
         "[done] transfer {} bytes={} files={} carrier={} duration={} {status}",
         c.transfer_id,
         c.bytes,
         c.files,
         if c.tcp_fallback_used { "gRPC" } else { "TCP" },
         format_ms(c.duration_ms),
     );
 }

