183:    pub fn from_file_stem(stem: &str) -> Option<Self> {
184:        let mut parts = stem.split('.');
185:        let (run_id, participant, role, attempt) =
186:            (parts.next()?, parts.next()?, parts.next()?, parts.next()?);
187:        if parts.next().is_some() {
188:            return None;
