190:        let number: u32 = attempt.parse().ok()?;
191:        // `parse` also takes "+1" and "01", which `file_stem` never writes.
192:        if number.to_string() != attempt {
193:            return None;
194:        }
195:        Self::new(run_id, participant, Role::parse(role)?, number).ok()
196:    }
