1412:impl Iterator for LogLines {
1413:    type Item = io::Result<LogLine>;
1414:
1415:    fn next(&mut self) -> Option<Self::Item> {
1416:        while !self.done {
1417:            self.buf.clear();
1418:            match self.reader.read_until(b'\n', &mut self.buf) {
1419:                Ok(0) => self.done = true,
1420:                Ok(_) => {
1421:                    self.line += 1;
1422:                    let ended = self.buf.ends_with(b"\n");
1423:                    let text = self.buf.trim_ascii();
1424:                    if text.is_empty() {
1425:                        continue;
1426:                    }
1427:                    if !self.checked {
1428:                        self.checked = true;
1429:                        if let Err(error) = check_header(text) {
1430:                            self.done = true;
1431:                            return Some(Err(error));
1432:                        }
1433:                    }
1434:                    return Some(Ok(match serde_json::from_slice::<Event>(text) {
1435:                        Ok(event) => LogLine::Event(event),
1436:                        Err(_) => LogLine::Unreadable {
1437:                            line: self.line,
1438:                            torn: !ended,
1439:                        },
1440:                    }));
1441:                }
1442:                Err(error) => {
1443:                    self.done = true;
1444:                    return Some(Err(error));
1445:                }
1446:            }
1447:        }
1448:        None
1449:    }
1450:}
