732:/// Take the key's lock and create its partial. Fails rather than touch a
733:/// log another writer owns or one this key already has.
734:fn open_partial(dir: &Path, stem: &str) -> io::Result<(File, File)> {
735:    fs::create_dir_all(dir)?;
736:    let lock_path = path_of(dir, stem, LOCK_SUFFIX);
737:    let lock = open_lock_file(&lock_path)?;
738:    match lock.try_lock() {
739:        Ok(()) => {}
740:        Err(TryLockError::WouldBlock) => {
741:            return Err(io::Error::other("another writer has this log open"))
742:        }
743:        Err(TryLockError::Error(error)) => return Err(error),
744:    }
745:    let created = if path_of(dir, stem, FINISHED_SUFFIX).exists() {
746:        Err(io::Error::new(
747:            io::ErrorKind::AlreadyExists,
748:            "this run already has a finished log",
749:        ))
750:    } else {
751:        // A partial already here is an earlier writer's record of this key;
752:        // never append to it or truncate it.
753:        OpenOptions::new()
754:            .write(true)
755:            .create_new(true)
756:            .open(path_of(dir, stem, PARTIAL_SUFFIX))
757:    };
758:    match created {
759:        Ok(file) => Ok((lock, file)),
760:        Err(error) => {
761:            drop(lock);
762:            let _ = fs::remove_file(&lock_path);
763:            Err(error)
764:        }
765:    }
766:}
