780:/// Compress the partial into `<stem>.jsonl.gz` — through a temp file and one
781:/// rename, so a reader or a crash sees either no finished log or a whole
782:/// one — then remove the partial. The finished log keeps the partial's
783:/// modified time, so pruning orders a recovered log by when its run wrote.
784:fn compress_into_place(dir: &Path, stem: &str, header: Option<&[u8]>) -> io::Result<PathBuf> {
785:    let partial = path_of(dir, stem, PARTIAL_SUFFIX);
786:    let temp = path_of(dir, stem, TEMP_SUFFIX);
787:    let finished = path_of(dir, stem, FINISHED_SUFFIX);
788:    if let Err(error) = write_compressed(&partial, &temp, &finished, header) {
789:        let _ = fs::remove_file(&temp);
790:        return Err(error);
791:    }
792:    sync_dir(dir);
793:    // The finished log is whole now; a partial left by a failure here is
794:    // removed by `recover`.
795:    if let Err(error) = fs::remove_file(&partial) {
796:        log::warn!(
797:            "job logs: could not remove {} after finishing it: {error}",
798:            partial.display()
799:        );
800:    }
801:    Ok(finished)
802:}
803:
804:/// `header`, when given, goes first: a rebuilt `run-start` for a log whose
805:/// own was lost.
806:fn write_compressed(
807:    partial: &Path,
808:    temp: &Path,
809:    finished: &Path,
810:    header: Option<&[u8]>,
811:) -> io::Result<()> {
812:    let mut input = File::open(partial)?;
813:    let modified = input.metadata()?.modified()?;
814:    let mut encoder = GzEncoder::new(BufWriter::new(File::create(temp)?), Compression::fast());
815:    if let Some(header) = header {
816:        encoder.write_all(header)?;
817:    }
818:    io::copy(&mut input, &mut encoder)?;
819:    let output = encoder
820:        .finish()?
821:        .into_inner()
822:        .map_err(|error| error.into_error())?;
823:    output.set_modified(modified)?;
824:    output.sync_all()?;
825:    drop(output);
826:    fs::rename(temp, finished)
827:}
