840:/// What [`recover`] did.
841:#[derive(Clone, Debug, Default, PartialEq, Eq)]
842:pub struct Recovery {
843:    /// Logs this call finished, closed as interrupted unless they already
844:    /// held their `run-end`.
845:    pub finished: Vec<PathBuf>,
846:    /// Partials left alone because a running writer still owns them.
847:    pub live: usize,
848:    /// Logs that could not be recovered, and why; they stay as they are for
849:    /// the next attempt.
850:    pub problems: Vec<String>,
851:}
852:
853:/// Finish every log in `dir` that a stopped process left behind (run at
854:/// startup). A partial whose lock is free has no writer: it gets a `run-end`
855:/// marked interrupted — unless it already ends with one, the crash having
856:/// come while it was being compressed — and is compressed into place.
857:/// Partials a running writer holds are left alone.
858:pub fn recover(dir: &Path) -> Recovery {
859:    let mut recovery = Recovery::default();
860:    let entries = match fs::read_dir(dir) {
861:        Ok(entries) => entries,
862:        Err(error) if error.kind() == io::ErrorKind::NotFound => return recovery,
863:        Err(error) => {
864:            recovery
865:                .problems
866:                .push(format!("could not read {}: {error}", dir.display()));
867:            return recovery;
868:        }
869:    };
870:    let mut stems: Vec<String> = Vec::new();
871:    for entry in entries.flatten() {
872:        let name = entry.file_name();
873:        let Some(name) = name.to_str() else { continue };
874:        let Some(stem) = name
875:            .strip_suffix(PARTIAL_SUFFIX)
876:            .or_else(|| name.strip_suffix(TEMP_SUFFIX))
877:        else {
878:            continue;
879:        };
880:        if LogKey::from_file_stem(stem).is_some() && !stems.iter().any(|seen| seen == stem) {
881:            stems.push(stem.to_string());
882:        }
883:    }
884:    stems.sort();
885:    for stem in stems {
886:        match recover_one(dir, &stem) {
887:            Ok(Recovered::Finished(path)) => recovery.finished.push(path),
888:            Ok(Recovered::Live) => recovery.live += 1,
889:            Ok(Recovered::Tidied) => {}
890:            Err(error) => recovery.problems.push(format!("{stem}: {error}")),
891:        }
892:    }
893:    recovery
894:}
895:
896:enum Recovered {
897:    Finished(PathBuf),
898:    Live,
899:    /// Only leftovers of a log already finished were removed.
900:    Tidied,
901:}
902:
903:fn recover_one(dir: &Path, stem: &str) -> io::Result<Recovered> {
904:    let lock_path = path_of(dir, stem, LOCK_SUFFIX);
905:    let lock = open_lock_file(&lock_path)?;
906:    match lock.try_lock() {
907:        Ok(()) => {}
908:        Err(TryLockError::WouldBlock) => return Ok(Recovered::Live),
909:        Err(TryLockError::Error(error)) => return Err(error),
910:    }
911:    let partial = path_of(dir, stem, PARTIAL_SUFFIX);
912:    let recovered = if !partial.exists() {
913:        // A temp file whose partial is gone.
914:        remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
915:        Recovered::Tidied
916:    } else if path_of(dir, stem, FINISHED_SUFFIX).exists() {
917:        // Finished before the crash; only removing the partial was lost.
918:        fs::remove_file(&partial)?;
919:        remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
920:        Recovered::Tidied
921:    } else {
922:        let lost_start = close_interrupted(&partial)?;
923:        // Review cr-jlfix1-1: typed reading needs the header, so a log whose
924:        // start was lost (a crash before its first sync) gets one rebuilt
925:        // from its name, at the front of the finished file.
926:        let header = match (lost_start, LogKey::from_file_stem(stem)) {
927:            (true, Some(key)) => Some(rebuilt_header(&key, &partial)?),
928:            _ => None,
929:        };
930:        Recovered::Finished(compress_into_place(dir, stem, header.as_deref())?)
931:    };
932:    drop(lock);
933:    let _ = fs::remove_file(&lock_path);
934:    Ok(recovered)
935:}
