948:fn close_interrupted(partial: &Path) -> io::Result<bool> {
949:    let mut last = None;
950:    let mut lost_start = true;
951:    let mut first = true;
952:    let mut lines = decode(File::open(partial)?)?;
953:    let mut buf = Vec::new();
954:    loop {
955:        buf.clear();
956:        if lines.read_until(b'\n', &mut buf)? == 0 {
957:            break;
958:        }
959:        let text = buf.trim_ascii();
960:        if text.is_empty() {
961:            continue;
962:        }
963:        if first {
964:            first = false;
965:            lost_start = check_header(text).is_err();
