967:        if let Ok(event) = serde_json::from_slice::<Event>(text) {
968:            last = Some(event);
969:        }
970:    }
971:    if let Some(Event {
972:        body: EventBody::RunEnd { .. },
973:        ..
974:    }) = last
975:    {
976:        return Ok(lost_start);
977:    }
978:    let mut file = OpenOptions::new().read(true).append(true).open(partial)?;
979:    let modified = file.metadata()?.modified()?;
980:    let mut line = Vec::new();
981:    // A torn last line gets its end, so the new event is a line of its own.
982:    if file.metadata()?.len() > 0 {
983:        let mut byte = [0u8; 1];
