989:    }
990:    serde_json::to_writer(
991:        &mut line,
992:        &Event {
993:            ts_ms: now_ms(),
994:            seq: last.map_or(0, |event| event.seq + 1),
995:            body: EventBody::RunEnd {
996:                outcome: Outcome::Interrupted,
997:                detail: Some(if lost_start {
998:                    format!("{RECOVERED_NOTE}{LOST_START_NOTE}")
