1373:/// Check a log's first line: it must be the `run-start` header, of this
1374:/// format and a version this build reads (reviews cr-jl1a-2, cr-jlfix1-1).
1375:/// Read as untyped JSON, so a newer header's fields are never forced into
1376:/// this version's shape. Anything else — another kind, a damaged or missing
1377:/// first line, a file that is not a job log — is refused rather than read
1378:/// as the current version; [`decode`] shows such a file's lines as stored.
1379:/// (Recovery gives a log whose start was lost a header of its own.)
1380:fn check_header(line: &[u8]) -> io::Result<()> {
1381:    use serde_json::Value;
1382:    let invalid = |message: String| Err(io::Error::new(io::ErrorKind::InvalidData, message));
1383:    let not_a_log = || {
1384:        invalid(
1385:            "not a blit job log, or its first line is damaged \
1386:             (`blit jobs log --json` shows its lines as stored)"
1387:                .into(),
1388:        )
1389:    };
1390:    let Ok(Value::Object(header)) = serde_json::from_slice::<Value>(line) else {
1391:        return not_a_log();
1392:    };
1393:    if header.get("kind").and_then(Value::as_str) != Some("run-start") {
1394:        return not_a_log();
1395:    }
1396:    let format = header.get("format").and_then(Value::as_str).unwrap_or("");
1397:    if format != FORMAT {
1398:        return invalid(format!("not a blit job log (format {format:?})"));
1399:    }
1400:    match header.get("version").and_then(Value::as_u64) {
1401:        // Every version this build knows reads as the current one; when
1402:        // VERSION moves past 1, an older version's migration goes here.
1403:        Some(version) if version <= u64::from(VERSION) => Ok(()),
1404:        Some(version) => invalid(format!(
1405:            "this job log is version {version}; this blit reads versions up to {VERSION} \
1406:             (`blit jobs log --json` shows it as stored)"
1407:        )),
1408:        None => invalid("the job log's run-start names no version".into()),
1409:    }
1410:}
