1044:/// Remove finished logs in `dir` beyond the newest `keep`, newest by when
1045:/// each run last wrote to its log; returns the logs removed.
1046:///
1047:/// Holds `dir`'s prune lock throughout, so two runs finishing at once do not
1048:/// race, and touches only finished logs: never a partial (a running log, or
1049:/// one not yet recovered) and never a file that is not a log. Waits for the
1050:/// lock, so call it from blocking code.
1051:pub fn prune(dir: &Path, keep: usize) -> io::Result<Vec<PathBuf>> {
1052:    let lock = open_lock_file(&dir.join(PRUNE_LOCK))?;
1053:    lock.lock()?;
1054:    let mut finished = Vec::new();
1055:    for entry in fs::read_dir(dir)?.flatten() {
1056:        let name = entry.file_name();
1057:        let Some(stem) = name.to_str().and_then(|n| n.strip_suffix(FINISHED_SUFFIX)) else {
1058:            continue;
1059:        };
1060:        if LogKey::from_file_stem(stem).is_none() {
1061:            continue;
1062:        }
1063:        let Ok(meta) = entry.metadata() else { continue };
1064:        let Ok(modified) = meta.modified() else {
1065:            continue;
1066:        };
1067:        if meta.is_file() {
1068:            finished.push((modified, entry.path()));
1069:        }
1070:    }
1071:    // Newest first; names break ties so the order is the same every time.
1072:    finished.sort_by(|a, b| b.cmp(a));
1073:    let mut removed = Vec::new();
1074:    for (_, path) in finished.into_iter().skip(keep) {
1075:        match fs::remove_file(&path) {
1076:            Ok(()) => removed.push(path),
1077:            Err(error) => log::warn!("job logs: could not prune {}: {error}", path.display()),
1078:        }
1079:    }
1080:    Ok(removed)
1081:}
