1084:/// still going (or not yet recovered); `None` if there is neither.
1085:pub fn find_log(dir: &Path, key: &LogKey) -> Option<FoundLog> {
1086:    let stem = key.file_stem();
1087:    let finished = path_of(dir, &stem, FINISHED_SUFFIX);
1088:    let partial = path_of(dir, &stem, PARTIAL_SUFFIX);
1089:    let found = |path: PathBuf, finished: bool| FoundLog {
1090:        key: key.clone(),
1091:        path,
1092:        finished,
1093:    };
1094:    // Finished, partial, then finished again: a run that finishes between the
1095:    // first two looks is still found.
1096:    if finished.is_file() {
1097:        return Some(found(finished, true));
1098:    }
1099:    if partial.is_file() {
1100:        return Some(found(partial, false));
1101:    }
1102:    finished.is_file().then(|| found(finished, true))
1103:}
