1125:    let mut found: Vec<FoundLog> = Vec::new();
1126:    for entry in entries.flatten() {
1127:        let name = entry.file_name();
1128:        let Some(name) = name.to_str() else { continue };
1129:        let (stem, finished) = if let Some(stem) = name.strip_suffix(FINISHED_SUFFIX) {
1130:            (stem, true)
1131:        } else if let Some(stem) = name.strip_suffix(PARTIAL_SUFFIX) {
1132:            (stem, false)
1133:        } else {
1134:            continue;
1135:        };
1136:        let Some(key) = LogKey::from_file_stem(stem) else {
1137:            continue;
1138:        };
