1201:fn describe(body: &EventBody) -> String {
1202:    let seconds = |ms: u64| format!("{:.1}s", ms as f64 / 1000.0);
1203:    match body {
1204:        EventBody::RunStart(start) => {
1205:            let host = if start.host.is_empty() {
1206:                &start.participant
1207:            } else {
1208:                &start.host
1209:            };
1210:            let mut text = format!(
1211:                "start    {} {} -> {} (job {}, {} on {host}, attempt {}, blit {})",
1212:                start.run.verb,
1213:                start.run.source,
1214:                start.run.destination,
1215:                start.run_id,
1216:                start.role.as_str(),
1217:                start.attempt,
1218:                start.build,
1219:            );
1220:            if !start.run.options.is_empty() {
1221:                text.push_str(&format!(" options: {}", start.run.options.join(" ")));
1222:            }
1223:            text
1224:        }
1225:        EventBody::Phase { name, state } => {
1226:            let state = match state {
1227:                PhaseState::Start => "started",
1228:                PhaseState::End => "ended",
1229:            };
1230:            format!("phase    {name} {state}")
1231:        }
1232:        EventBody::FileCopied { path, bytes, raw } => {
1233:            let path = shown(path, raw);
1234:            match bytes {
1235:                Some(bytes) => {
1236:                    format!("copied   {path} ({})", crate::display::format_bytes(*bytes))
1237:                }
1238:                None => format!("copied   {path}"),
1239:            }
1240:        }
1241:        EventBody::FileSent { path, raw } => format!("sent     {}", shown(path, raw)),
1242:        EventBody::FileDeleted { path, raw } => format!("deleted  {}", shown(path, raw)),
1243:        EventBody::FileFailed { path, reason, raw } => {
1244:            format!("FAILED   {}: {reason}", shown(path, raw))
1245:        }
1246:        EventBody::Stall { idle_ms, detail } => {
1247:            format!("stall    nothing moved for {}: {detail}", seconds(*idle_ms))
1248:        }
1249:        EventBody::Diagnostic { message } => format!("info     {message}"),
1250:        EventBody::Summary(summary) => format!(
1251:            "summary  {} copied ({}), {} deleted, {} failed, in {}",
1252:            summary.files_copied,
1253:            crate::display::format_bytes(summary.bytes_copied),
1254:            summary.files_deleted,
1255:            summary.files_failed,
1256:            seconds(summary.elapsed_ms),
1257:        ),
1258:        EventBody::RunEnd { outcome, detail } => {
1259:            let outcome = match outcome {
1260:                Outcome::Ok => "ok",
1261:                Outcome::Failed => "failed",
1262:                Outcome::Cancelled => "cancelled",
1263:                Outcome::Interrupted => "interrupted",
1264:            };
1265:            match detail {
1266:                Some(detail) => format!("end      {outcome}: {detail}"),
1267:                None => format!("end      {outcome}"),
1268:            }
1269:        }
1270:        EventBody::LogIncomplete { reason } => {
1271:            format!("LOG INCOMPLETE  {reason}; nothing after this was kept")
1272:        }
1273:        EventBody::Unknown => "unknown  an event from a newer blit".into(),
1274:    }
1275:}
