1282:pub fn machine_id(dir: &Path) -> io::Result<String> {
1283:    let path = dir.join(MACHINE_ID_FILE);
1284:    if !path.exists() {
1285:        use rand::{rngs::SysRng, TryRng};
1286:        let mut bits = [0u8; 16];
1287:        SysRng
1288:            .try_fill_bytes(&mut bits)
1289:            .map_err(|error| io::Error::other(format!("system RNG unavailable: {error}")))?;
1290:        let id: String = bits.iter().map(|byte| format!("{byte:02x}")).collect();
1291:        fs::create_dir_all(dir)?;
1292:        match OpenOptions::new().write(true).create_new(true).open(&path) {
1293:            Ok(mut file) => {
1294:                file.write_all(format!("{id}\n").as_bytes())?;
1295:                file.sync_all()?;
1296:            }
1297:            // Another process made it first; read theirs.
1298:            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
1299:            Err(error) => return Err(error),
1300:        }
1301:    }
1302:    let text = fs::read_to_string(&path)?;
1303:    let id = text.trim();
1304:    if check_id("machine ID", id).is_err() {
1305:        return Err(io::Error::new(
1306:            io::ErrorKind::InvalidData,
1307:            format!("{} does not hold a machine ID", path.display()),
1308:        ));
1309:    }
1310:    Ok(id.to_string())
