423:impl LogWriter {
424:    /// Start the log `key` in `dir`, recording `run-start` with `run`.
425:    /// Finishing it later prunes `dir` to the newest `keep` finished logs.
426:    ///
427:    /// Returns at once: the folder and files are made on the writer's
428:    /// thread, and a failure there leaves an incomplete log, never an error.
429:    pub fn start(dir: &Path, key: LogKey, run: RunInfo, keep: usize) -> Self {
430:        Self::start_tuned(dir, key, run, Tuning::new(keep))
431:    }
432:
433:    fn start_tuned(dir: &Path, key: LogKey, run: RunInfo, tuning: Tuning) -> Self {
434:        let (tx, rx) = flume::bounded(tuning.queue_depth);
435:        let started_ms = now_ms();
436:        let dir = dir.to_path_buf();
437:        let spawned = std::thread::Builder::new()
438:            .name("blit-job-log".into())
439:            .spawn(move || write_log(dir, key, run, started_ms, rx, tuning));
440:        let (thread, spawn_error) = match spawned {
441:            Ok(thread) => (Some(thread), None),
442:            Err(error) => (
443:                None,
444:                Some(format!("could not start the log writer: {error}")),
445:            ),
446:        };
447:        Self {
448:            sender: LogSender { tx },
449:            thread,
450:            spawn_error,
451:        }
452:    }
453:
454:    pub fn sender(&self) -> LogSender {
455:        self.sender.clone()
456:    }
457:
458:    pub fn record(&self, body: EventBody) {
459:        self.sender.record(body);
