513:fn write_log(
514:    dir: PathBuf,
515:    key: LogKey,
516:    run: RunInfo,
517:    started_ms: u64,
518:    rx: flume::Receiver<Msg>,
519:    tuning: Tuning,
520:) -> LogReport {
521:    #[cfg(test)]
522:    if let Some(gate) = &tuning.start_gate {
523:        let _ = gate.recv();
524:    }
525:    let mut writer = Writer::open(dir, key.file_stem(), &tuning);
526:    writer.append(
527:        started_ms,
528:        EventBody::RunStart(Box::new(RunStart {
529:            format: FORMAT.into(),
530:            version: VERSION,
531:            run_id: key.run_id,
532:            participant: key.participant,
533:            role: key.role,
534:            attempt: key.attempt,
535:            host: hostname::get()
536:                .map(|name| name.to_string_lossy().into_owned())
537:                .unwrap_or_default(),
538:            build: crate::transfer_session::session_build_id().into(),
539:            run,
540:        })),
541:    );
542:    let (outcome, detail) = loop {
543:        match rx.recv_timeout(writer.until_sync(tuning.sync_interval)) {
544:            Ok(Msg::Event { ts_ms, body }) => {
545:                let phase = matches!(body, EventBody::Phase { .. });
546:                writer.append(ts_ms, body);
547:                if phase || writer.until_sync(tuning.sync_interval).is_zero() {
548:                    writer.sync();
549:                }
550:            }
551:            Ok(Msg::Finish { outcome, detail }) => break (outcome, detail),
552:            Err(flume::RecvTimeoutError::Timeout) => writer.sync(),
553:            Err(flume::RecvTimeoutError::Disconnected) => {
554:                break (Outcome::Interrupted, Some(UNCLOSED_NOTE.into()))
555:            }
556:        }
557:    };
558:    // A handle still recording now fails at once instead of waiting on a
559:    // queue no one drains.
560:    drop(rx);
561:    writer.append(now_ms(), EventBody::RunEnd { outcome, detail });
562:    writer.sync();
563:    writer.finish(tuning.keep)
