567:struct Writer {
568:    dir: PathBuf,
569:    stem: String,
570:    /// The sidecar lock, held from opening the log until it is finished.
571:    lock: Option<File>,
572:    /// The partial being appended to; `None` once logging has stopped.
573:    file: Option<PartialFile>,
574:    report: LogReport,
575:}
576:
577:impl Writer {
578:    fn open(dir: PathBuf, stem: String, tuning: &Tuning) -> Self {
579:        let mut writer = Writer {
580:            dir,
581:            stem,
582:            lock: None,
583:            file: None,
584:            report: LogReport::default(),
585:        };
586:        match open_partial(&writer.dir, &writer.stem) {
587:            Ok((lock, file)) => {
588:                writer.report.path = Some(path_of(&writer.dir, &writer.stem, PARTIAL_SUFFIX));
589:                writer.lock = Some(lock);
590:                writer.file = Some(PartialFile {
591:                    out: BufWriter::with_capacity(64 * 1024, file),
592:                    line: Vec::new(),
593:                    next_seq: 0,
594:                    unsynced: false,
595:                    last_sync: Instant::now(),
596:                    #[cfg(test)]
597:                    fail_at_seq: tuning.fail_at_seq,
598:                });
599:            }
600:            Err(error) => {
601:                writer.report.problem = Some(format!(
602:                    "could not start the log in {}: {error}",
603:                    writer.dir.display()
604:                ))
605:            }
606:        }
607:        #[cfg(not(test))]
608:        let _ = tuning;
609:        writer
610:    }
611:
612:    fn append(&mut self, ts_ms: u64, body: EventBody) {
613:        let Some(file) = self.file.as_mut() else {
614:            return;
615:        };
616:        if let Err(error) = file.append(ts_ms, body) {
617:            self.stop(error);
618:        }
619:    }
620:
621:    fn sync(&mut self) {
622:        let Some(file) = self.file.as_mut() else {
623:            return;
624:        };
625:        if !file.unsynced {
626:            return;
627:        }
628:        if let Err(error) = file.sync() {
629:            self.stop(error);
630:        }
631:    }
632:
633:    /// How long until what was written is due to be synced.
634:    fn until_sync(&self, interval: Duration) -> Duration {
635:        match &self.file {
636:            Some(file) if file.unsynced => interval.saturating_sub(file.last_sync.elapsed()),
637:            _ => IDLE_WAIT,
638:        }
639:    }
640:
641:    /// Logging stops at the first write that fails; the transfer goes on.
642:    fn stop(&mut self, error: io::Error) {
643:        let reason = format!("could not write the log: {error}");
644:        if let Some(mut file) = self.file.take() {
645:            // Best effort. The failed write may have left part of a line, so
646:            // end it first and the marker stands as a line of its own.
647:            let _ = file.out.write_all(b"\n").and_then(|()| {
648:                file.append(
649:                    now_ms(),
650:                    EventBody::LogIncomplete {
651:                        reason: reason.clone(),
652:                    },
653:                )?;
654:                file.sync()
655:            });
656:        }
657:        self.report.problem.get_or_insert(reason);
658:    }
659:
660:    fn finish(mut self, keep: usize) -> LogReport {
661:        self.report.complete = self.file.is_some();
662:        // Close the partial before compressing it; it was synced already.
663:        drop(self.file.take());
664:        let Some(lock) = self.lock.take() else {
665:            return self.report;
666:        };
667:        match compress_into_place(&self.dir, &self.stem, None) {
668:            Ok(finished) => self.report.path = Some(finished),
669:            Err(error) => {
670:                self.report.problem.get_or_insert_with(|| {
671:                    format!("could not finish the log (the next start finishes it): {error}")
672:                });
673:                return self.report;
674:            }
675:        }
676:        drop(lock);
677:        let _ = fs::remove_file(path_of(&self.dir, &self.stem, LOCK_SUFFIX));
678:        if let Err(error) = prune(&self.dir, keep) {
679:            log::warn!("job logs: pruning {} failed: {error}", self.dir.display());
680:        }
681:        self.report
682:    }
683:}
