685:struct PartialFile {
686:    out: BufWriter<File>,
687:    /// Each event is serialized here first, so the file only ever receives
688:    /// whole lines.
689:    line: Vec<u8>,
690:    next_seq: u64,
691:    unsynced: bool,
692:    last_sync: Instant,
693:    #[cfg(test)]
694:    fail_at_seq: Option<u64>,
695:}
696:
697:impl PartialFile {
698:    fn append(&mut self, ts_ms: u64, body: EventBody) -> io::Result<()> {
699:        self.line.clear();
700:        serde_json::to_writer(
701:            &mut self.line,
702:            &Event {
703:                ts_ms,
704:                seq: self.next_seq,
705:                body,
706:            },
707:        )?;
708:        self.line.push(b'\n');
709:        #[cfg(test)]
710:        if self.fail_at_seq == Some(self.next_seq) {
711:            // Half the line reaches the file, as a write cut short by a full
712:            // disk leaves it.
713:            self.fail_at_seq = None;
714:            self.out.write_all(&self.line[..self.line.len() / 2])?;
715:            return Err(io::Error::other("injected write failure"));
716:        }
717:        self.out.write_all(&self.line)?;
718:        self.next_seq += 1;
719:        self.unsynced = true;
720:        Ok(())
721:    }
722:
723:    fn sync(&mut self) -> io::Result<()> {
724:        self.out.flush()?;
725:        self.out.get_ref().sync_data()?;
726:        self.unsynced = false;
727:        self.last_sync = Instant::now();
728:        Ok(())
729:    }
730:}
